// ---------- Relatório 2D do tratamento ----------
// Modelo: 1ª página = imagem geral dos leques do realce (planejado azul × executado vermelho);
// depois uma página por leque = imagem do leque + tabela FURO / PLANEJADO / EXECUTADO / DESVIO (cm) / OBSERVAÇÃO.
// As imagens vêm do software de topografia (print/exportação) e ficam guardadas neste aparelho (IndexedDB).
// Logos Trust + ERO (PNG, 943×216) — usadas no cabeçalho de todos os relatórios em PDF.
const R2D_LOGO_B64 = "";
const R2D_LOGO_W = 58, R2D_LOGO_H = 58 * 216 / 943;
let r2dDBp = null;
function r2dDB(){
  if(r2dDBp) return r2dDBp;
  r2dDBp = new Promise((ok, falha)=>{ try{ const rq = indexedDB.open('relatorio2d-imagens-v1', 1);
    rq.onupgradeneeded = ()=> rq.result.createObjectStore('img'); rq.onsuccess = ()=> ok(rq.result); rq.onerror = ()=> falha(rq.error); }catch(e){ falha(e); } });
  return r2dDBp;
}
async function r2dImg(op, chave, valor){
  try{ const d = await r2dDB();
    return await new Promise((ok, falha)=>{ const tx = d.transaction('img', op === 'get' ? 'readonly' : 'readwrite'), st = tx.objectStore('img');
      const rq = op === 'get' ? st.get(chave) : op === 'put' ? st.put(valor, chave) : st.delete(chave); rq.onsuccess = ()=> ok(rq.result); rq.onerror = ()=> falha(rq.error); });
  }catch(e){ return null; }
}
// Reduz a imagem (máx. 1800 px no maior lado, JPEG) para não pesar no aparelho nem no PDF.
// Guarda a imagem em alta qualidade: até 3200 px, PNG sem perda quando a origem é PNG (prints de desenho técnico),
// ou JPEG qualidade 95 nos demais casos. O PDF reduz depois, só se passar de ~300 dpi.
function r2dReduzir(arq){
  return new Promise((ok, falha)=>{
    const url = URL.createObjectURL(arq), im = new Image();
    im.onload = ()=>{
      const k = Math.min(1, 3200 / Math.max(im.width, im.height)), cv = document.createElement('canvas');
      cv.width = Math.round(im.width * k); cv.height = Math.round(im.height * k);
      const c = cv.getContext('2d'); c.fillStyle = '#fff'; c.fillRect(0, 0, cv.width, cv.height);
      c.imageSmoothingEnabled = true; c.imageSmoothingQuality = 'high'; c.drawImage(im, 0, 0, cv.width, cv.height);
      URL.revokeObjectURL(url);
      const jpeg = ()=> cv.toBlob(b=> b ? ok({ blob:b, w:cv.width, h:cv.height }) : falha(new Error('imagem inválida')), 'image/jpeg', 0.95);
      if(/png|webp|gif|bmp/i.test(arq.type || '')) cv.toBlob(b=>{ if(b && b.size <= 6 * 1024 * 1024) ok({ blob:b, w:cv.width, h:cv.height }); else jpeg(); }, 'image/png');
      else jpeg();
    };
    im.onerror = ()=>{ URL.revokeObjectURL(url); falha(new Error('Não consegui ler essa imagem.')); };
    im.src = url;
  });
}
// Prepara a imagem para o PDF: mantém o formato (PNG/JPEG) e só reduz se passar de 300 dpi no tamanho em que será impressa.
async function r2dImagemParaPDF(reg, wMm){
  const alvo = Math.ceil(wMm / 25.4 * 300), png = /png/i.test(reg.blob.type || '');
  if(reg.w <= alvo * 1.1) return { data: await r2dParaDataURL(reg.blob), fmt: png ? 'PNG' : 'JPEG' };
  const url = URL.createObjectURL(reg.blob);
  try{
    const im = await new Promise((ok, no)=>{ const i = new Image(); i.onload = ()=> ok(i); i.onerror = no; i.src = url; });
    const cv = document.createElement('canvas'); cv.width = alvo; cv.height = Math.round(alvo * reg.h / reg.w);
    const c = cv.getContext('2d'); c.fillStyle = '#fff'; c.fillRect(0, 0, cv.width, cv.height); c.imageSmoothingQuality = 'high'; c.drawImage(im, 0, 0, cv.width, cv.height);
    return { data: cv.toDataURL(png ? 'image/png' : 'image/jpeg', 0.93), fmt: png ? 'PNG' : 'JPEG' };
  } finally { URL.revokeObjectURL(url); }
}
const r2dParaDataURL = blob => new Promise(ok=>{ const r = new FileReader(); r.onload = ()=> ok(r.result); r.readAsDataURL(blob); });

function r2dLequesDoRealce(anelId){
  return checklistLeques.filter(c=>c.anelId === anelId).map(estadoTratativaLeque)
    .sort((x,y)=> codigoLequeCk(x.c).localeCompare(codigoLequeCk(y.c), undefined, { numeric:true }));
}
function r2dObsAuto(f){ return f.obsTratamento || (f.obstruido ? (furoDetonado(f) ? 'Detonado' : 'Obstruído') : ''); }
const r2dNum = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? '' : String(Math.round(Number(v) * 100) / 100).replace('.', ',');
const r2dLer = s => { const t = String(s).trim().replace(',', '.'); return t === '' || isNaN(Number(t)) ? null : Number(t); };

let r2dEstado = null; // { anelId, incluir:Set(lequeId), aberto:lequeId|null, urls:{chave:url} }

async function abrirRelatorio2D(anelId){
  const a = aneis.find(x=>x.id === (anelId || anelAtivoId)); if(!a){ showToast('Nenhum realce ativo.'); return; }
  const lista = r2dLequesDoRealce(a.id).filter(e=>e.tratado);
  if(!lista.length){ showToast('Esse realce ainda não tem leques tratados.', { tipo:'aviso' }); return; }
  r2dEstado = { anelId: a.id, incluir: new Set(lista.map(e=>e.c.id)), aberto: null, urls: {}, projeto: (()=>{ try{ return localStorage.getItem('r2d_projeto') || ''; }catch(e){ return ''; } })() };
  await r2dRender();
}

async function r2dUrl(chave){
  if(r2dEstado.urls[chave] !== undefined) return r2dEstado.urls[chave];
  const v = await r2dImg('get', chave); r2dEstado.urls[chave] = v && v.blob ? URL.createObjectURL(v.blob) : null; return r2dEstado.urls[chave];
}

async function r2dRender(){
  const st = r2dEstado; if(!st) return; const a = aneis.find(x=>x.id === st.anelId); const lista = r2dLequesDoRealce(a.id).filter(e=>e.tratado); // só os tratados entram
  const geral = await r2dUrl('geral:' + a.id);
  const linhas = [];
  for(const e of lista){
    const id = e.c.id, cod = codigoLequeCk(e.c), url = await r2dUrl('leque:' + id), aberto = st.aberto === id, fs = checklistFurosDoLeque(id).slice().sort((x,y)=> String(x.numero).localeCompare(String(y.numero), undefined, { numeric:true }));
    linhas.push(`<div class="r2d-leque ${aberto ? 'aberto' : ''}">
      <div class="r2d-l1">
        <label class="r2d-inc"><input type="checkbox" data-r2d-inc="${id}" ${st.incluir.has(id) ? 'checked' : ''}><b class="r2d-cod">${escHtml(cod)}</b></label>
        <span class="r2d-sit ok">tratado${e.c.tratadoEm ? ' ' + fmtDataBR(e.c.tratadoEm) : ''}</span>
        <span class="r2d-img-st">${url ? '🖼 imagem ✓' : 'sem imagem'}</span>
        <button type="button" class="ghost" data-r2d-abrir="${id}" aria-expanded="${aberto}">${aberto ? 'Fechar ▲' : 'Imagem e tabela ▼'}</button>
      </div>
      ${aberto ? `<div class="r2d-corpo">
        <div class="r2d-img-linha">${url ? `<img src="${url}" alt="imagem do ${escHtml(cod)}">` : `<div class="r2d-img-vazia">${cava ? 'Anexe a imagem do realce' : 'Anexe a imagem deste leque'}</div>`}
          <div class="r2d-img-acoes"><button type="button" class="steel" data-r2d-anexar="leque:${id}">${url ? 'Trocar imagem' : 'Anexar imagem'}</button>${url ? `<button type="button" class="ghost" data-r2d-remover="leque:${id}">Remover</button>` : ''}</div></div>
        <div class="r2d-tab-scroll"><table class="r2d-tab"><thead><tr><th>Furo</th><th>Planejado (m)</th><th>Executado (m)</th><th>Desvio (cm)</th><th>Observação</th></tr></thead><tbody>
          ${fs.map(f=>`<tr data-furo="${f.id}"><td><b>${escHtml(String(f.numero))}</b></td><td>${r2dNum(f.metragemEsperada)}</td>
            <td><input inputmode="decimal" data-r2d-campo="metragem" value="${r2dNum(f.metragem > 0 ? f.metragem : '')}" aria-label="Executado do furo ${escHtml(String(f.numero))}"></td>
            <td><input inputmode="decimal" data-r2d-campo="desvioCm" value="${r2dNum(f.desvioCm)}" aria-label="Desvio em cm do furo ${escHtml(String(f.numero))}"></td>
            <td><input type="text" data-r2d-campo="obsTratamento" maxlength="60" value="${escHtml(r2dObsAuto(f))}" placeholder="Obstruído, Varado…" aria-label="Observação do furo ${escHtml(String(f.numero))}"></td></tr>`).join('') || '<tr><td colspan="5">Sem furos.</td></tr>'}
        </tbody></table></div></div>` : ''}
    </div>`);
  }
  el('modal-root').innerHTML = `<div class="modal-overlay" id="modal-overlay"><div class="modal-box modal-box-larga r2d-box">
    <p style="font-weight:700;margin:0 0 4px;">Relatório 2D · ${escHtml(a.nome)}</p>
    <div class="hint" style="margin-bottom:10px;">Página 1: imagem geral dos leques. Depois, uma página por leque tratado, com a imagem e a tabela. As imagens ficam guardadas neste aparelho.</div>
    <label class="r2d-proj" for="r2d-projeto"><b>Projeto</b> <small>(aparece no cabeçalho do PDF; deixe vazio para não mostrar)</small></label>
    <input type="text" id="r2d-projeto" maxlength="80" value="${escHtml(st.projeto || '')}" placeholder="Ex.: ERO – Pilar" autocomplete="off">
    <div class="r2d-geral"><b>1 · Imagem geral dos leques</b>
      ${geral ? `<img src="${geral}" alt="imagem geral dos leques">` : '<div class="r2d-img-vazia">Anexe a imagem com todos os leques do realce</div>'}
      <div class="r2d-img-acoes"><button type="button" class="steel" data-r2d-anexar="geral:${a.id}">${geral ? 'Trocar imagem' : 'Anexar imagem'}</button>${geral ? `<button type="button" class="ghost" data-r2d-remover="geral:${a.id}">Remover</button>` : ''}</div></div>
    <b style="display:block;margin:12px 0 4px;">2 · Leques tratados <span id="r2d-cont">(${lista.filter(e=>st.incluir.has(e.c.id)).length} de ${lista.length} no relatório)</span></b>
    <div class="rel-atalhos"><button type="button" class="ghost" id="r2d-todos">Marcar todos</button><button type="button" class="ghost" id="r2d-nenhum">Desmarcar todos</button></div>
    <div class="r2d-lista">${linhas.join('')}</div>
    <input type="file" id="r2d-arq" accept="image/*" hidden>
    <div class="modal-actions"><button class="ghost" id="r2d-fechar">Fechar</button><button class="steel" id="r2d-pdf">Gerar PDF</button></div>
  </div></div>`;
}

document.addEventListener('click', async ev=>{
  const t = ev.target; if(!r2dEstado || !t.closest || !t.closest('.r2d-box') && t.id !== 'modal-overlay') return;
  if(t.id === 'modal-overlay' || t.id === 'r2d-fechar'){ Object.values(r2dEstado.urls).forEach(u=> u && URL.revokeObjectURL(u)); r2dEstado = null; el('modal-root').innerHTML = ''; return; }
  if(t.id === 'r2d-todos' || t.id === 'r2d-nenhum'){ r2dEstado.incluir = t.id === 'r2d-todos' ? new Set(r2dLequesDoRealce(r2dEstado.anelId).filter(e=>e.tratado).map(e=>e.c.id)) : new Set(); return r2dRender(); }
  if(t.id === 'r2d-pdf'){ return gerarRelatorio2DPDF(); }
  const ab = t.closest('[data-r2d-abrir]'); if(ab){ const id = ab.dataset.r2dAbrir; r2dEstado.aberto = r2dEstado.aberto === id ? null : id; return r2dRender(); }
  const an = t.closest('[data-r2d-anexar]'); if(an){ const inp = el('r2d-arq'); inp.dataset.chave = an.dataset.r2dAnexar; inp.value = ''; inp.click(); return; }
  const rm = t.closest('[data-r2d-remover]'); if(rm){ const k = rm.dataset.r2dRemover; await r2dImg('del', k); if(r2dEstado.urls[k]) URL.revokeObjectURL(r2dEstado.urls[k]); delete r2dEstado.urls[k]; return r2dRender(); }
});
document.addEventListener('input', ev=>{
  if(!r2dEstado || ev.target.id !== 'r2d-projeto') return;
  r2dEstado.projeto = ev.target.value; try{ localStorage.setItem('r2d_projeto', ev.target.value); }catch(e){}
});
document.addEventListener('change', async ev=>{
  const t = ev.target; if(!r2dEstado) return;
  if(t.id === 'r2d-arq' && t.files && t.files[0]){
    try{ const r = await r2dReduzir(t.files[0]); const k = t.dataset.chave; await r2dImg('put', k, { blob: r.blob, w: r.w, h: r.h });
      if(r2dEstado.urls[k]) URL.revokeObjectURL(r2dEstado.urls[k]); delete r2dEstado.urls[k]; showToast('Imagem anexada.', { tipo:'ok' }); }
    catch(e){ showToast(e.message || 'Não consegui anexar a imagem.', { tipo:'erro' }); }
    return r2dRender();
  }
  const inc = t.closest && t.closest('[data-r2d-inc]');
  if(inc){ const id = inc.dataset.r2dInc; if(inc.checked) r2dEstado.incluir.add(id); else r2dEstado.incluir.delete(id);
    const n = r2dLequesDoRealce(r2dEstado.anelId).filter(e=>e.tratado).length, c = el('r2d-cont'); if(c) c.textContent = `(${r2dEstado.incluir.size} de ${n} no relatório)`; return; }
  const campo = t.dataset && t.dataset.r2dCampo; if(!campo) return;
  r2dSalvarCampoFuro(t, campo);
});
// Grava um campo da tabela do leque (executado, desvio, observação) — usado no Relatório 2D e em "Dados do leque".
function r2dSalvarCampoFuro(t, campo){
  const f = checklistFuros.find(x=>x.id === t.closest('tr').dataset.furo); if(!f) return;
  const reg = { id: f.id };
  if(campo === 'obsTratamento'){ const v = t.value.trim(); f.obsTratamento = (v === r2dObsAuto({ ...f, obsTratamento:'' })) ? '' : v; reg.obs_tratamento = f.obsTratamento || null; }
  else { const v = r2dLer(t.value); if(campo === 'metragem'){ f.metragem = v; reg.metragem = v; } else { f.desvioCm = v; reg.desvio_cm = v; } t.value = r2dNum(v); }
  enfileirar('checklist_furos', 'update', reg); salvarChecklistFurosLocal();
}

// ---------- Dados do leque (preenchidos na hora do tratamento, antes do relatório geral) ----------
let dlEstado = null; // { id, url }
async function abrirDadosLeque(id){ dlEstado = { id, url: undefined }; await dlRender(); }
function dlContarPreenchidos(){ if(!dlEstado) return 0; return checklistFurosDoLeque(dlEstado.id).reduce((n, f)=> n + (f.desvioCm != null && f.desvioCm !== '' ? 1 : 0) + (f.obsTratamento ? 1 : 0), 0); }
function dlFechar(){ if(dlEstado && dlEstado.url) URL.revokeObjectURL(dlEstado.url); if(dlEstado && dlEstado.urlTab) URL.revokeObjectURL(dlEstado.urlTab); dlEstado = null; el('modal-root').innerHTML = ''; }
async function dlRender(){
  const st = dlEstado; if(!st) return;
  const c = checklistLeques.find(x=>x.id === st.id); if(!c){ dlFechar(); return; }
  const a = aneis.find(x=>x.id === c.anelId) || { nome:'' }, cod = codigoLequeCk(c);
  if(st.url === undefined){ const v = await r2dImg('get', 'leque:' + c.id); st.url = v && v.blob ? URL.createObjectURL(v.blob) : null; }
  const cava = c.tipo === 'cava';
  if(cava && st.urlTab === undefined){ const v = await r2dImg('get', 'tabela:' + c.id); st.urlTab = v && v.blob ? URL.createObjectURL(v.blob) : null; }
  const fs = checklistFurosDoLeque(c.id).slice().sort((x,y)=> String(x.numero).localeCompare(String(y.numero), undefined, { numeric:true }));
  el('modal-root').innerHTML = `<div class="modal-overlay" id="modal-overlay"><div class="modal-box modal-box-larga r2d-box dl-box">
    <p style="font-weight:700;margin:0 0 2px;">Dados do leque · ${escHtml(cod)}</p>
    <div class="hint" style="margin-bottom:10px;">${escHtml(a.nome)} · ${c.tratado ? 'tratado' + (c.tratadoEm ? ' em ' + fmtDataBR(c.tratadoEm) : '') : 'ainda não marcado como tratado'}. O que você preencher aqui já vai para o Relatório 2D e para o relatório geral.</div>
    <div class="dl-corpo">
    ${cava ? `<div class="r2d-img-linha dl-img-tabela"><div class="dl-img-rot">🖼 Imagem da tabela <small class="hint">(vai no fim do relatório em PDF)</small></div>${st.urlTab ? `<img src="${st.urlTab}" alt="imagem da tabela">` : '<div class="r2d-img-vazia">Anexe a imagem da tabela</div>'}
      <div class="r2d-img-acoes"><button type="button" class="steel" data-dl-anexar-tab>${st.urlTab ? 'Trocar imagem' : 'Anexar imagem da tabela'}</button>${st.urlTab ? '<button type="button" class="ghost" data-dl-remover-tab>Remover</button>' : ''}<small class="hint">guardada só neste aparelho</small></div></div>` : ''}
    <div class="r2d-img-linha">${st.url ? `<img src="${st.url}" alt="imagem do ${escHtml(cod)}">` : `<div class="r2d-img-vazia">${cava ? 'Anexe a imagem do realce' : 'Anexe a imagem deste leque'}</div>`}
      <div class="r2d-img-acoes"><button type="button" class="steel" data-dl-anexar>${st.url ? 'Trocar imagem' : 'Anexar imagem'}</button>${st.url ? '<button type="button" class="ghost" data-dl-remover>Remover</button>' : ''}<small class="hint">a imagem fica guardada só neste aparelho</small></div></div>
    <div class="r2d-tab-scroll"><table class="r2d-tab"><colgroup><col style="width:11%"><col style="width:17%"><col style="width:19%"><col style="width:18%"><col style="width:35%"></colgroup><thead><tr><th>Furo</th><th>Plan. (m)</th><th>Exec. (m)</th><th>Desvio (cm)</th><th>Observação</th></tr></thead><tbody>
      ${fs.map(f=>`<tr data-furo="${f.id}"><td><b>${escHtml(String(f.numero))}</b></td><td>${r2dNum(f.metragemEsperada)}</td>
        <td><input inputmode="decimal" data-dl-campo="metragem" value="${r2dNum(f.metragem > 0 ? f.metragem : '')}" aria-label="Executado do furo ${escHtml(String(f.numero))}"></td>
        <td><input inputmode="decimal" data-dl-campo="desvioCm" value="${r2dNum(f.desvioCm)}" aria-label="Desvio em cm do furo ${escHtml(String(f.numero))}"></td>
        <td><input type="text" data-dl-campo="obsTratamento" maxlength="60" value="${escHtml(r2dObsAuto(f))}" placeholder="Obstruído, Varado…" aria-label="Observação do furo ${escHtml(String(f.numero))}"></td></tr>`).join('') || '<tr><td colspan="5">Esse leque ainda não tem furos.</td></tr>'}
    </tbody></table></div>
    </div>
    <input type="file" id="dl-arq" accept="image/*" hidden><input type="file" id="dl-arq-tab" accept="image/*" hidden>
    <div class="modal-actions"><button class="ghost" id="dl-fechar">Fechar</button><button class="ghost dl-salvar" id="dl-salvar" title="guarda o que já foi preenchido, sem marcar o leque como tratado">Salvar parcial</button>${c.tratado ? '' : '<button class="steel" id="dl-tratar">Marcar como tratado</button>'}</div>
  </div></div>`;
}
document.addEventListener('click', async ev=>{
  const t = ev.target; if(!dlEstado || !t.closest) return;
  if(t.id === 'modal-overlay' || t.id === 'dl-fechar') return dlFechar();
  if(t.id === 'dl-salvar'){ const n = dlContarPreenchidos(); if(document.activeElement && document.activeElement.blur) document.activeElement.blur(); dlFechar(); showToast(n ? `Dados parciais salvos (${n} ${n === 1 ? 'campo preenchido' : 'campos preenchidos'}). O leque continua como está.` : 'Nada preenchido ainda.', { tipo: n ? 'ok' : 'aviso' }); return; }
  if(t.id === 'dl-tratar'){ const id = dlEstado.id; dlFechar(); return marcarLequeTratado(id); }
  if(t.closest('[data-dl-anexar-tab]')){ const inp = el('dl-arq-tab'); inp.value = ''; inp.click(); return; }
  if(t.closest('[data-dl-remover-tab]')){ await r2dImg('del', 'tabela:' + dlEstado.id); if(dlEstado.urlTab) URL.revokeObjectURL(dlEstado.urlTab); dlEstado.urlTab = undefined; return dlRender(); }
  if(t.closest('[data-dl-anexar]')){ const inp = el('dl-arq'); inp.value = ''; inp.click(); return; }
  if(t.closest('[data-dl-remover]')){ await r2dImg('del', 'leque:' + dlEstado.id); if(dlEstado.url) URL.revokeObjectURL(dlEstado.url); dlEstado.url = undefined; return dlRender(); }
});
document.addEventListener('change', async ev=>{
  const t = ev.target; if(!dlEstado) return;
  if(t.id === 'dl-arq-tab' && t.files && t.files[0]){
    try{ const r = await r2dReduzir(t.files[0]); await r2dImg('put', 'tabela:' + dlEstado.id, { blob: r.blob, w: r.w, h: r.h });
      if(dlEstado.urlTab) URL.revokeObjectURL(dlEstado.urlTab); dlEstado.urlTab = undefined; showToast('Imagem da tabela anexada.', { tipo:'ok' }); }
    catch(e){ showToast(e.message || 'Não consegui anexar a imagem.', { tipo:'erro' }); }
    return dlRender();
  }
  if(t.id === 'dl-arq' && t.files && t.files[0]){
    try{ const r = await r2dReduzir(t.files[0]); await r2dImg('put', 'leque:' + dlEstado.id, { blob: r.blob, w: r.w, h: r.h });
      if(dlEstado.url) URL.revokeObjectURL(dlEstado.url); dlEstado.url = undefined; showToast('Imagem anexada.', { tipo:'ok' }); }
    catch(e){ showToast(e.message || 'Não consegui anexar a imagem.', { tipo:'erro' }); }
    return dlRender();
  }
  const campo = t.dataset && t.dataset.dlCampo; if(campo) r2dSalvarCampoFuro(t, campo);
});

async function gerarRelatorio2DPDF(){
  const st = r2dEstado; if(!st) return;
  if(!window.jspdf){ showToast('Biblioteca de PDF ainda carregando, tente novamente em 1s.'); return; }
  const a = aneis.find(x=>x.id === st.anelId), lista = r2dLequesDoRealce(a.id).filter(e=>e.tratado && st.incluir.has(e.c.id));
  const geral = await r2dImg('get', 'geral:' + a.id);
  if(!geral && !lista.length){ showToast('Marque ao menos um leque (ou anexe a imagem geral).', { tipo:'aviso' }); return; }
  showToast('Gerando o PDF…');
  const doc = new window.jspdf.jsPDF(), NOME = a.nome;
  // Marca d'água ATRÁS do conteúdo (desenhada antes de tudo em cada página) e bem suave; as imagens (fundo opaco) a cobrem.
  const marca = ()=>{ const T = 130; doc.saveGraphicsState(); doc.setGState(new doc.GState({ opacity: 0.05 }));
    try{ doc.addImage('data:image/png;base64,'+LOGO_MARCA_DAGUA_B64, 'PNG', 210 - T * 0.72, 297 - T * 0.72, T, T); }catch(e){} doc.restoreGraphicsState(); };
  const novaPagina = ()=>{ doc.addPage(); marca(); };
  marca();
  const cab = (cod)=>{
    doc.setDrawColor(0); doc.setLineWidth(0.3); doc.rect(15, 12, cod ? 100 : 60, 12); doc.setFont(undefined,'bold'); doc.setFontSize(11); doc.text(NOME, 17, 19.5, { maxWidth: cod ? 70 : 56 });
    if(cod){ doc.line(87, 12, 87, 24); doc.text(cod, 101, 19.5, { align:'center' }); }
    try{ doc.addImage('data:image/png;base64,'+R2D_LOGO_B64, 'PNG', 195 - R2D_LOGO_W, 9, R2D_LOGO_W, R2D_LOGO_H); }catch(e){}
  };
  const infoLinha = ()=>{ doc.setFont(undefined,'normal'); doc.setFontSize(8.5); doc.setTextColor(110);
    doc.text([PROJ ? 'Projeto: ' + PROJ : '', 'Gerado em ' + new Date().toLocaleDateString('pt-BR')].filter(Boolean).join('   ·   '), 15, 31, { maxWidth: 150 }); doc.setTextColor(0); };
  const imagem = async (reg, x, y, wMax, hMax)=>{
    if(!reg){ doc.setDrawColor(190); doc.setLineDashPattern([2,2],0); doc.rect(x, y, wMax, Math.min(hMax, 60)); doc.setLineDashPattern([],0); doc.setFontSize(9); doc.setTextColor(140); doc.text('(sem imagem anexada)', x + wMax/2, y + 30, { align:'center' }); doc.setTextColor(0); return Math.min(hMax, 60); }
    let w = wMax, h = w * reg.h / reg.w; if(h > hMax){ h = hMax; w = h * reg.w / reg.h; }
    const pr = await r2dImagemParaPDF(reg, w); doc.addImage(pr.data, pr.fmt, x + (wMax - w)/2, y, w, h, undefined, 'SLOW'); return h;
  };
  const legenda = (y, geral)=>{ doc.setFont(undefined,'bold'); doc.setFontSize(10); doc.text('LEGENDA', 15, y); doc.text(geral ? 'AZUL: PLANEJADO' : 'LINHA AZUL: PLANEJADO', 15, y + 5); doc.text(geral ? 'VERMELHO: EXECUTADO' : 'TRACEJADO VERMELHA: EXECUTADO', 15, y + 10); };
  // Página 1 — cabeçalho completo (logo, título, gerado em e projeto) + imagem geral
  try{ doc.addImage('data:image/png;base64,'+R2D_LOGO_B64, 'PNG', 195 - R2D_LOGO_W, 9, R2D_LOGO_W, R2D_LOGO_H); }catch(e){}
  doc.setFont(undefined,'bold'); doc.setFontSize(14); doc.text('RELATÓRIO 2D DE TRATAMENTO', 15, 16);
  doc.setFont(undefined,'normal'); doc.setFontSize(9); doc.setTextColor(120); doc.text('Gerado em ' + new Date().toLocaleDateString('pt-BR'), 15, 22); doc.setTextColor(0);
  doc.setDrawColor(180); doc.setLineWidth(0.2); doc.line(15, 30, 195, 30);
  const PROJ = (st.projeto || '').trim();
  let y1 = 36;
  if(PROJ){ doc.setFontSize(10); doc.text('Projeto:', 15, 38); doc.text(PROJ, 42, 38, { maxWidth: 150 }); doc.line(15, 44, 195, 44); y1 = 48; }
  doc.setDrawColor(0); doc.setLineWidth(0.3); doc.rect(15, y1, 100, 10); doc.setFont(undefined,'bold'); doc.setFontSize(11); doc.text(NOME, 17, y1 + 6.8, { maxWidth: 96 });
  y1 += 14; const hG = await imagem(geral, 15, y1, 180, 285 - y1 - 20); legenda(y1 + hG + 8, true);
  // Uma página por leque
  for(const e of lista){
    novaPagina(); cab(codigoLequeCk(e.c)); infoLinha();
    const fs = checklistFurosDoLeque(e.c.id).slice().sort((x,y)=> String(x.numero).localeCompare(String(y.numero), undefined, { numeric:true }));
    // A tabela fica sempre encostada no fim da página; a legenda logo acima; a imagem ocupa o espaço que sobra.
    const linhaH = 6.2, tabH = (fs.length + 1) * linhaH, fimPag = 285, yTab = fimPag - tabH, yLeg = yTab - 15;
    const reg = await r2dImg('get', 'leque:' + e.c.id);
    await imagem(reg, 15, 38, 180, Math.max(40, yLeg - 6 - 38));
    legenda(yLeg); let y = yTab;
    const COLS = [['FURO',15],['PLANEJADO (m)',34],['EXECUTADO (m)',34],['DESVIO (CM)',28],['OBSERVAÇÃO',69]];
    doc.setLineWidth(0.2); doc.setDrawColor(0); doc.setFontSize(8);
    let x = 15; doc.setFont(undefined,'bold'); COLS.forEach(([t,w])=>{ doc.rect(x, y, w, linhaH); doc.text(t, x + w/2, y + 4.2, { align:'center' }); x += w; }); y += linhaH;
    doc.setFont(undefined,'normal'); doc.setFontSize(9);
    fs.forEach(f=>{
      const cel = [String(f.numero), r2dNum(f.metragemEsperada), r2dNum(f.metragem > 0 ? f.metragem : ''), r2dNum(f.desvioCm), r2dObsAuto(f)];
      x = 15; COLS.forEach(([,w],i)=>{ doc.rect(x, y, w, linhaH); doc.setFont(undefined, i === 3 && cel[i] ? 'bold' : 'normal'); doc.text(cel[i], x + w/2, y + 4.3, { align:'center', maxWidth: w - 2 }); x += w; }); y += linhaH;
    });
  }
  // Final do relatório: imagem da tabela (realce a céu aberto), uma página por grupo que tenha a imagem.
  for(const e of lista.filter(x=>x.c.tipo === 'cava')){
    const regT = await r2dImg('get', 'tabela:' + e.c.id); if(!regT) continue;
    novaPagina(); cab(''); infoLinha();
    doc.setFont(undefined,'bold'); doc.setFontSize(11); doc.text('TABELA', 15, 40);
    await imagem(regT, 15, 46, 180, 285 - 46);
  }
  await baixarOuCompartilharPDF(doc, `relatorio-2d_${String(NOME).replace(/[^\w-]+/g,'_')}_${new Date().toISOString().slice(0,10)}.pdf`, true);
  showToast('Relatório 2D gerado.', { tipo:'ok' });
}
